      "slurm": "#!/bin/bash\n#SBATCH -p qcpu_exp\n#SBATCH -A DD-23-135\n#SBATCH -n 1 \n#SBATCH --comment \"use:vtune=2022.2.0\"\n#SBATCH -t 0:10:00\n#SBATCH --mail-type END\n#SBATCH -J AVS-vtune\n\ncd $SLURM_SUBMIT_DIR\n\nml intel-compilers/2022.1.0 CMake/3.23.1-GCCcore-11.3.0 VTune/2022.2.0-intel-2021b\n\n[ -d build_vtune ] && rm -rf build_vtune\n[ -d build_vtune ] || mkdir build_vtune\ncd build_vtune\n\nCC=icc CXX=icpc cmake ..\nmake\n\nfor threads in 18 36; do\n    for builder in \"ref\" \"loop\" \"tree\"; do\n        rm -rf vtune-${builder}-${threads}\n        vtune -collect threading -r vtune-${builder}-${threads} -app-working-dir . -- ./PMC --builder ${builder} -t ${threads} --grid 128 ../data/bun_zipper_res3.pts\n    done\ndone",
      "flux": "#!/bin/bash\n\n# Flux directives translated from SLURM\n#FLUX: -n 1 \n#FLUX: -t 0:10:00\n#FLUX: -q qcpu_exp\n\n#\n# --- Omitted SLURM options and explanations ---\n#\n# -A DD-23-135\n#   Omitted. Flux accounting is typically managed through system configuration or job\n#   submission options, not a standard batch directive.\n#\n# --comment \"use:vtune=2022.2.0\"\n#   Omitted. This is a non-standard directive, likely a site-specific hint for the\n#   scheduler or operators, and has no equivalent in Flux.\n#\n# --mail-type END\n#   Omitted. Flux core does not have built-in support for email notifications via\n#   batch directives.\n#\n# -J AVS-vtune\n#   Omitted. The job name in Flux is generally set during submission (e.g.,\n#   'flux submit --job-name=AVS-vtune ...') or via the FLUX_JOB_NAME\n#   environment variable, not through a script directive.\n#\n# Note on CPU/Memory resources:\n#   The original script did not request a specific number of CPUs or memory. The job\n#   will receive a default allocation (typically one core), which may be insufficient\n#   for the threaded application being run.\n#\n\n# The SLURM variable $SLURM_SUBMIT_DIR is replaced by the Flux equivalent $FLUX_SUBMIT_DIR\ncd $FLUX_SUBMIT_DIR\n\nml intel-compilers/2022.1.0 CMake/3.23.1-GCCcore-11.3.0 VTune/2022.2.0-intel-2021b\n\n[ -d build_vtune ] && rm -rf build_vtune\n[ -d build_vtune ] || mkdir build_vtune\ncd build_vtune\n\nCC=icc CXX=icpc cmake ..\nmake\n\nfor threads in 18 36; do\n    for builder in \"ref\" \"loop\" \"tree\"; do\n        rm -rf vtune-${builder}-${threads}\n        vtune -collect threading -r vtune-${builder}-${threads} -app-working-dir . -- ./PMC --builder ${builder} -t ${threads} --grid 128 ../data/bun_zipper_res3.pts\n    done\ndone\n",
