      "slurm": "#!/bin/bash\n#SBATCH -t 6:00:00\n#SBATCH -c 12\n#SBATCH --mem=24G\n#SBATCH -C intel\n#SBATCH --array=1-3\nsleep $((SLURM_ARRAY_TASK_ID*60))\n\nset -e\n\nexport AGALMA_DB=\"/gpfs/data/cdunn/analyses/agalma-siphonophora-20170501_reduced.sqlite\"\nexport BIOLITE_RESOURCES=\"threads=${SLURM_CPUS_ON_NODE},memory=${SLURM_MEM_PER_NODE}M\"\n\nIDS=(\n\tdbEST_CLYHEM\n\tNCBI_HYDMAG\n\tJGI_NEMVEC\n)\n\nID=${IDS[$SLURM_ARRAY_TASK_ID-1]}\necho $ID\n\nagalma import --id $ID\nagalma translate --id $ID",
      "flux": "#!/bin/bash\n#flux: -t 6:00:00\n\n# Requesting 12 CPUs for the job. The loop below will use these resources for each iteration.\n#flux: -c 12\n\n# The following Slurm constraint was not translated as this is not a standard Flux job option.\n# Feature requests are typically handled by submitting to a specific queue configured with those resources.\n# The job will run on any available node, which may impact performance if a specific CPU architecture is required.\n# #SBATCH -C intel\n\n# CRITICAL: The Slurm memory request (--mem=24G) could not be translated to a standard Flux directive.\n# This job will receive the default memory allocation, which is likely to be insufficient and may cause the job to fail.\n# #SBATCH --mem=24G\n\n# The original Slurm job array (--array=1-3) has been converted to a serial for-loop.\n# This means each task will run one after another, NOT in parallel.\n# The total runtime of this job will be the sum of the runtimes of the individual tasks.\n\nset -e\n\nexport AGALMA_DB=\"/gpfs/data/cdunn/analyses/agalma-siphonophora-20170501_reduced.sqlite\"\n\n# The BIOLITE_RESOURCES variable is hardcoded to the requested thread count.\n# The memory part is omitted as the memory request could not be translated.\nexport BIOLITE_RESOURCES=\"threads=12\"\n\nIDS=(\n\tdbEST_CLYHEM\n\tNCBI_HYDMAG\n\tJGI_NEMVEC\n)\n\nfor TASK_ID in {1..3}; do\n    echo \"--- Starting Task ID: ${TASK_ID} ---\"\n\n    # Stagger job start times using the loop variable.\n    sleep $((TASK_ID*60))\n\n    # Use the loop variable to index into the bash array.\n    ID=${IDS[$TASK_ID-1]}\n    echo \"Processing ID: $ID\"\n\n    agalma import --id $ID\n    agalma translate --id $ID\n\n    echo \"--- Finished Task ID: ${TASK_ID} ---\"\ndone\n",
