      "slurm": "#!/bin/bash\n#SBATCH -J PMDA_BM                  # name\n#SBATCH --partition=compute\n#SBATCH --nodes=6                        # Total number of nodes requested (16 cores/node). You may delete this line if wanted\n#SBATCH --ntasks-per-node=12            # Total number of mpi tasks requested\n#SBATCH --export=ALL\n#SBATCH -t 08:00:00                      # wall time (D-HH:MM)\n#SBATCH --mail-type=ALL                # Send a notification when the job starts, stops, or fails\n#SBATCH --mail-user=sfan19@asu.edu  # send-to address\n                      \nbash /home/sfan19/.bashrc\n\necho $SLURM_JOB_ID\necho $USER\n\nSCHEDULER=`hostname`\necho SCHEDULER: $SCHEDULER\ndask-scheduler --port=8786 &\nsleep 5\n\nhostnodes=`scontrol show hostnames $SLURM_NODELIST`\necho $hostnodes\n\nfor host in $hostnodes; do\n    echo \"Working on $host ....\"\n    ssh $host dask-worker --nprocs 12 --nthreads 1 $SCHEDULER:8786 &\n    sleep 1\ndone\n\n\npython benchmark_rms_distr.py /scratch/$USER/$SLURM_JOB_ID $SCHEDULER:8786",
      "flux": "#!/bin/bash\n# Flux job script translated from Slurm\n\n# --- Flux Directives ---\n# The job requests 6 nodes and a total of 72 tasks (12 per node), with 1 CPU per task.\n#flux: --job-name=PMDA_BM\n#flux: -q compute\n#flux: -N 6\n#flux: -n 72\n#flux: -c 1\n#flux: -t 08:00:00\n# --- End Flux Directives ---\n\n# The following SLURM directives were not translated as they are not standard Flux options.\n# #SBATCH --export=ALL (default behavior)\n# #SBATCH --mail-type=ALL\n# #SBATCH --mail-user=sfan19@asu.edu\n\n# Sourcing .bashrc is generally not recommended in batch scripts.\nbash /home/sfan19/.bashrc\n\necho \"Starting Dask cluster for job $FLUX_JOB_ID\"\n\n# Get the hostname of the first task (rank 0) to act as the scheduler\nSCHEDULER=$(flux exec -r 0 hostname)\necho \"Scheduler will run on: $SCHEDULER\"\n\n# Launch the Dask scheduler in the background on the first task\nflux exec -r 0 dask-scheduler --port=8786 & \nsleep 10 # Wait for scheduler to start\n\n# Launch Dask workers on all other tasks (ranks 1 through N-1)\n# The original script started 12 1-threaded workers per node. Our resource request of 12 tasks/node matches this.\nflux exec -r 1- dask-worker $SCHEDULER:8786 &\nsleep 10 # Wait for workers to connect\n\n# Run the client-side python script on the first task\nflux exec -r 0 python benchmark_rms_distr.py /scratch/$USER/$FLUX_JOB_ID $SCHEDULER:8786\n\n# Wait for all backgrounded processes (scheduler, workers) to finish\nwait\n",
