      "slurm": "#!/bin/bash\n#SBATCH --job-name=petscDMDA       # nom du job\n#SBATCH --nodes=1                  # Nombre de noeud\n#SBATCH --ntasks=4                 # Nombre total de processus MPI\n#SBATCH --hint=nomultithread       # 1 processus MPI par coeur physique (pas d'hyperthreading)\n#SBATCH --time=00:10:00            # Temps d\u2019ex\u00e9cution maximum demande (HH:MM:SS)\n#SBATCH --output=petscDMDA%j.out   # Nom du fichier de sortie\n#SBATCH --error=petscDMDA%j.out    # Nom du fichier d'erreur (ici commun avec la sortie)\n\n# on se place dans le r\u00e9pertoire de soumission\ncd ${SLURM_SUBMIT_DIR}\n\n# nettoyage des modules charges en interactif et herites par defaut\nmodule purge\n\n# chargement des modules\nsource ../../../petsc.sh\n\n# echo des commandes lanc\u00e9es\nset -x\n\n# ex\u00e9cution du code\ntime srun ./dmda.exe -da_grid_x 1000 -da_grid_y 1000 -ksp_type cg -pc_type hypre",
      "flux": "#!/bin/bash\n# Flux batch script converted from Slurm\n\n# NOTE: Run with: flux batch <this_script>\n\n# Slurm resources:\n#   --job-name=petscDMDA\n#   --nodes=1\n#   --ntasks=4\n#   --hint=nomultithread\n#   --time=00:10:00\n#   --output=petscDMDA%j.out\n#   --error=petscDMDA%j.out\n\n#flux: --job-name=petscDMDA\n#flux: -N 1\n#flux: -n 4\n#flux: --time-limit=10m\n\n# Omitted Slurm option: --hint=nomultithread\n# Flux SMT/hyperthreading control is site/config dependent; no portable equivalent.\n# Performance implication: ranks may be placed on logical CPUs with SMT enabled, which can affect performance/variability.\n\n# Omitted Slurm options: --output/--error with %j token and join stdout/stderr\n# Slurm's %j token (job id) and the \"join\" behavior are not portable in Flux batch directives.\n# Performance implication: none, but logs may overwrite/collide unless you choose unique filenames; stdout/stderr may be separated.\n\n# Slurm variable $SLURM_SUBMIT_DIR is not set under Flux.\n# Use the directory where `flux batch` was invoked.\ncd \"${FLUX_JOB_SUBMIT_DIR:-$PWD}\"\n\nmodule purge\n\n# Load PETSc environment\nsource ../../../petsc.sh\n\nset -x\n\n# Slurm used srun; under Flux, use flux-run to launch MPI ranks.\ntime flux run -n 4 ./dmda.exe -da_grid_x 1000 -da_grid_y 1000 -ksp_type cg -pc_type hypre\n",
