      "slurm": "#!/bin/bash -l\n#SBATCH --nodes=2  --time=04:00:00  \n#SBATCH -C gpu \n#SBATCH --account m1759\n#SBATCH --gres=gpu:8\n#SBATCH --exclusive\n#SBATCH -c 80\n\nmodule load pytorch/v1.4.0-gpu\nmodule list\nexport HDF5_USE_FILE_LOCKING=FALSE\n\nnodes=$(scontrol show hostnames $SLURM_JOB_NODELIST) # Getting the node names\nnodes_array=( $nodes )\nworker_num=$(($SLURM_JOB_NUM_NODES - 1))\n\nmaster_node=${nodes_array[0]}\n\nfor ((  i=0; i<=$worker_num; i++ ))\ndo\n  node_i=${nodes_array[$i]}\n  srun --nodes=1 --ntasks=1 -w $node_i python -m torch.distributed.launch --nproc_per_node=8 --nnodes=8 --node_rank=$i --master_addr=$master_node train.py --run_num=13 &\n  pids[${i}]=$!\n  echo \"Training started on node $i\"\ndone\n\n# Wait for completion\nfor pid in ${pids[*]}; do\n    wait $pid\ndone\n\ndate",
      "flux": "#!/bin/bash -l\n# Flux batch script converted from Slurm\n\n# NOTE: Run with: flux batch <this_script>\n\n# Slurm resources:\n#   --nodes=2\n#   --time=04:00:00\n#   -C gpu\n#   --account m1759\n#   --gres=gpu:8\n#   --exclusive\n#   -c 80\n\n# Map nodes/tasks/cores (portable subset).\n# Note: the original script launches 1 process per node that spawns 8 GPU workers via torch.distributed.\n#flux: -N 2\n#flux: -n 2\n#flux: -c 80\n#flux: --time-limit=4h\n\n# Omitted Slurm option: --gres=gpu:8\n# Flux GPU requests are site/config dependent (often via custom resource types).\n# Performance implication: job may start without GPUs (or with fewer GPUs), causing failure or severe slowdown.\n\n# Omitted Slurm option: -C gpu (constraint)\n# Flux constraints/feature selection are site-specific; no portable equivalent.\n# Performance implication: job may land on non-GPU nodes, causing failure.\n\n# Omitted Slurm option: --exclusive\n# Flux exclusivity is site/config dependent; no universally portable batch directive.\n# Performance implication: job may share nodes with other jobs, causing contention and reduced performance.\n\n# Omitted Slurm option: --account m1759\n# Flux accounting/project selection is site-specific; no portable equivalent.\n# Performance implication: job may be charged to a default account or be rejected by policy.\n\nmodule load pytorch/v1.4.0-gpu\nmodule list\nexport HDF5_USE_FILE_LOCKING=FALSE\n\n# Slurm variables/commands are not available under Flux (e.g., scontrol/SLURM_JOB_NODELIST).\n# Use Flux to obtain hostnames.\nmapfile -t nodes_array < <(flux resource list -n -o '{hosts}')\n\n# Best-effort: choose first host as master.\nmaster_node=${nodes_array[0]}\n\n# Launch one trainer per node under Flux.\n# Omitted Slurm option: -w (specific node selection)\n# Flux per-node placement is site/config dependent; no portable equivalent.\n# Performance implication: processes may not be pinned exactly as intended.\n\npids=()\nfor i in $(seq 0 $((${#nodes_array[@]} - 1))); do\n  flux run -n 1 -c 80 \\\n    python -m torch.distributed.launch \\\n      --nproc_per_node=8 \\\n      --nnodes=8 \\\n      --node_rank=$i \\\n      --master_addr=$master_node \\\n      train.py --run_num=13 &\n  pids[$i]=$!\n  echo \"Training started on node $i\"\ndone\n\nfor pid in ${pids[*]}; do\n  wait $pid\ndone\n\ndate\n",
