      "slurm": "#!/bin/bash\n#COBALT -q full-node\n#COBALT -n 1\n#COBALT -t 240\n#COBALT -A datascience\n#COBALT --attrs filesystems=home,grand,eagle,theta-fs0\n# Necessary for Bash shells\n. /etc/profile\n\n# Tensorflow optimized for A100 with CUDA 11\nmodule load conda/pytorch\n# module load conda/pytorch\n\n# Activate conda env\nconda activate pycords\n# conda activate base\nexport PYTHONPATH=/lus/grand/projects/datascience/ianwixom/expcifar:$PYTHONPATH\n\n# User Configuration\n# INIT_SCRIPT=$PWD/activate-dh.sh\nCOBALT_JOBSIZE=1\nRANKS_PER_NODE=8\n\n# Initialization of environment\n# source $INIT_SCRIPT\nmodule list\nmpirun -x LD_LIBRARY_PATH -x PYTHONPATH -x PATH -n $(( $COBALT_JOBSIZE * $RANKS_PER_NODE )) -N $RANKS_PER_NODE --hostfile $COBALT_NODEFILE python cifar10cordsmodel.py",
      "flux": "#!/bin/bash\n\n# Flux batch script converted from Cobalt\n# Note: Flux does not support in-script directives for resource specification\n# This script should be submitted with the following command:\n# flux batch -N 1 -n 8 -t 240m --job-name=cobalt_job script.sh\n#\n# Resource specifications:\n# -N 1         : 1 node (from -n 1)\n# -n 8         : 8 tasks (from RANKS_PER_NODE=8)\n# -t 240m      : 240 minute walltime (from -t 240)\n# --job-name=cobalt_job : job name (can be customized)\n#\n# Note: Total tasks = COBALT_JOBSIZE (1) \u00d7 RANKS_PER_NODE (8) = 8 tasks\n\n# Original Cobalt queue: full-node\n# Cobalt: -q full-node\n# Note: Flux does not have queues in the same way as Cobalt\n# Queue selection is handled through Flux's scheduling configuration\n# Performance impact: Job scheduling priority depends on site-specific Flux configuration\n# Consult site documentation for equivalent resource pools or queues\n\n# Original Cobalt account: datascience\n# Cobalt: -A datascience\n# Note: Flux uses banks/accounts through flux-accounting\n# Set at submission if flux-accounting is configured:\n# flux batch --setattr=bank=datascience ...\n# Performance impact: Without account specification, job may run under default account\n# which could affect priority, resource limits, or accounting tracking\n\n# Original Cobalt filesystems: home,grand,eagle,theta-fs0\n# Cobalt: --attrs filesystems=home,grand,eagle,theta-fs0\n# Note: Flux does not have a direct equivalent for filesystem attributes\n# Filesystem access depends on node configuration and mount points\n# Performance impact: Ensure required filesystems are mounted on target nodes\n# Consult site documentation for filesystem availability on Flux nodes\n\n# Original Cobalt nodes: 1\n# Flux: -N 1\n\n# Original Cobalt time: 240 minutes\n# Flux: -t 240m or -t 4h or -t 14400s\n\n# Bash profile initialization\n. /etc/profile\n\n# Module loading\nmodule load conda/pytorch\n# module load conda/pytorch\n\n# Conda environment activation\nconda activate pycords\n# conda activate base\n\n# Python path configuration\nexport PYTHONPATH=/lus/grand/projects/datascience/ianwixom/expcifar:$PYTHONPATH\n\n# User Configuration\n# INIT_SCRIPT=$PWD/activate-dh.sh\nCOBALT_JOBSIZE=1\nRANKS_PER_NODE=8\n\n# Initialization of environment\n# source $INIT_SCRIPT\nmodule list\n\n# MPI execution\n# Original: mpirun with Cobalt-specific options\n# Cobalt: mpirun -x LD_LIBRARY_PATH -x PYTHONPATH -x PATH -n $(( $COBALT_JOBSIZE * $RANKS_PER_NODE )) -N $RANKS_PER_NODE --hostfile $COBALT_NODEFILE\n# Flux: Use flux run for MPI job launching\n# Flux automatically handles node allocation and task distribution\n\n# Calculate total MPI ranks\nTOTAL_RANKS=$(( $COBALT_JOBSIZE * $RANKS_PER_NODE ))\n\n# Flux run command\n# -n specifies total number of tasks\n# -N specifies tasks per node (optional, Flux can distribute automatically)\n# flux run inherits environment variables by default\nflux run -n $TOTAL_RANKS -N $RANKS_PER_NODE python cifar10cordsmodel.py\n\n# Note on environment variable propagation:\n# Flux run automatically propagates environment variables\n# The -x flags from mpirun are not needed\n# LD_LIBRARY_PATH, PYTHONPATH, and PATH will be inherited\n\n# Note on hostfile:\n# Cobalt: --hostfile $COBALT_NODEFILE\n# Flux: Node allocation is handled internally by Flux\n# The flux run command automatically uses allocated resources\n# No explicit hostfile is needed\n\n# Complete submission command with all options:\n# flux batch -N 1 -n 8 -t 240m \\\n#   --job-name=cobalt_job \\\n#   --setattr=bank=datascience \\\n#   script.sh\n",
