      "slurm": "#!/bin/bash\n#SBATCH -N 1   # node count\n#SBATCH --ntasks-per-node=4\n#SBATCH --ntasks-per-socket=2\n#SBATCH --cpus-per-task=7\n#SBATCH -t 24:00:00\n# SBATCH --mem=32G\n#SBATCH --gres=gpu:4\n#SBATCH --mail-type=begin\n#SBATCH --mail-type=end\n#SBATCH --mail-user=tgartner@princeton.edu\n\n# load environment\nmodule load cudatoolkit/10.0\nmodule load cudnn/cuda-10.0/7.6.3\nmodule load openmpi/gcc/3.1.3/64\n#module load fftw\nsource /home/tgartner/Software-deepmd-kit-1.0/tensorflow-venv/bin/activate\nmodule load /home/tgartner/modulefiles/plumed-tg\n# export OMP_NUM_THREADS=1\n\nif [ -f \"Sampledone.txt\" ]; then\n    echo \"Simulation finished\"\nelif ! grep -q 'ERROR' slurm*; then\n    echo \"Continuing NPT sampling\"\n    sbatch --dependency=afterany:$SLURM_JOB_ID run.sample.qs\n    # run NPT sampling\n    mpirun /home/tgartner/Software-deepmd-kit-1.0/lammps-3Mar20/src/lmp_mpi -i in.lammps.sample -e screen\nelse\n    echo \"There is an error\"\nfi",
      "flux": "#!/bin/bash\n# Flux batch script converted from Slurm\n\n# NOTE: Run with: flux batch <this_script>\n\n# Slurm resources:\n#   -N 1\n#   --ntasks-per-node=4\n#   --ntasks-per-socket=2\n#   --cpus-per-task=7\n#   -t 24:00:00\n#   --gres=gpu:4\n#   --mail-type=begin/end\n#   --mail-user=tgartner@princeton.edu\n#   (mem directive commented out)\n\n# Map to Flux: 1 node, 4 tasks, 7 cores per task (28 cores total)\n#flux: -N 1\n#flux: -n 4\n#flux: -c 7\n#flux: --time-limit=24h\n\n# Omitted Slurm option: --gres=gpu:4\n# Flux GPU requests are site/config dependent (often via custom resource types).\n# Performance implication: job may start without GPUs (or fewer than 4), causing failure or severe slowdown.\n\n# Omitted Slurm option: --ntasks-per-socket=2\n# Flux does not have a universally portable directive for per-socket placement.\n# Performance implication: rank placement/NUMA locality may differ, potentially reducing performance.\n\n# Omitted Slurm options: --mail-type and --mail-user\n# Flux does not provide a universal, built-in email notification directive in batch scripts.\n# Performance implication: none on runtime performance, but you will not receive automatic job emails.\n\n# NOTE: Slurm dependency resubmission (sbatch --dependency=afterany:$SLURM_JOB_ID ...) has no portable Flux equivalent.\n# Performance implication: the follow-on sampling job will not be scheduled automatically; you must orchestrate chaining externally.\n\nmodule load cudatoolkit/10.0\nmodule load cudnn/cuda-10.0/7.6.3\nmodule load openmpi/gcc/3.1.3/64\nsource /home/tgartner/Software-deepmd-kit-1.0/tensorflow-venv/bin/activate\nmodule load /home/tgartner/modulefiles/plumed-tg\n\nif [ -f \"Sampledone.txt\" ]; then\n    echo \"Simulation finished\"\nelif ! grep -q 'ERROR' slurm* 2>/dev/null; then\n    echo \"Continuing NPT sampling\"\n    # Run NPT sampling across 4 ranks.\n    flux run -n 4 -c 7 /home/tgartner/Software-deepmd-kit-1.0/lammps-3Mar20/src/lmp_mpi -i in.lammps.sample -e screen\nelse\n    echo \"There is an error\"\nfi\n",
